from ortools.sat.python import cp_model
import numpy as np
import json

def solve_truck_loading():
    n_parcels = 10
    volumes = [45, 30, 25, 40, 35, 20, 15, 50, 10, 20]
    capacity = 100

    max_trucks = n_parcels

    model = cp_model.CpModel()

    x = {}
    for i in range(n_parcels):
        for j in range(max_trucks):
            x[i, j] = model.NewBoolVar(f"x_{i}_{j}")

    y = {}
    for j in range(max_trucks):
        y[j] = model.NewBoolVar(f"y_{j}")

    for i in range(n_parcels):
        model.Add(sum(x[i, j] for j in range(max_trucks)) == 1)

    for j in range(max_trucks):
        total_volume = sum(volumes[i] * x[i, j] for i in range(n_parcels))
        model.Add(total_volume <= capacity * y[j])

    for i in range(n_parcels):
        for j in range(max_trucks):
            model.Add(x[i, j] <= y[j])

    model.Minimize(sum(y[j] for j in range(max_trucks)))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        used_trucks = []
        for j in range(max_trucks):
            if solver.Value(y[j]) == 1:
                used_trucks.append(j)

        truck_loads = {}
        for j in used_trucks:
            parcels_in_truck = []
            for i in range(n_parcels):
                if solver.Value(x[i, j]) == 1:
                    parcels_in_truck.append(i)
            truck_loads[j] = parcels_in_truck

        result_truck_loads = []
        for j in sorted(used_trucks):
            result_truck_loads.append(truck_loads[j])

        print(json.dumps({
            "num_trucks": len(used_trucks),
            "truck_loads": result_truck_loads
        }))

    else:
        print(json.dumps({
            "num_trucks": 0,
            "truck_loads": []
        }))

if __name__ == "__main__":
    solve_truck_loading()
